-- utf8, which is the one library that has to agree about what a
-- character is, and the byte-level string functions that go with it:
-- 'byte', 'char', 'sub', 'rep', 'reverse', 'lower', 'upper', 'len'.
local function show(...)
  local n = select('#', ...)
  local t = {}
  for i = 1, n do
    local v = (select(i, ...))
    if type(v) == "string" then t[i] = string.format("%q", v)
    elseif v == nil then t[i] = "nil"
    else
      local ok, s = pcall(tostring, v)
      t[i] = ok and s or ("<" .. type(v) .. ">")
    end
  end
  return table.concat(t, "|")
end
local function rec(f, ...) return show(pcall(f, ...)) end
local function P(...) print(...) end
-- Show bytes as numbers so an invalid sequence is visible.
local function hex(s)
  if type(s) ~= "string" then return tostring(s) end
  local t = {}
  for i = 1, #s do t[i] = string.format("%02x", s:byte(i)) end
  return table.concat(t, " ")
end

-- 'utf8.char' raises for a code point it cannot encode, so every call
-- below goes through pcall; 'hx' keeps the byte dump for the ones that
-- answer.
local function hx(...)
  local ok, v = pcall(utf8.char, ...)
  return ok and hex(v) or ("ERR:" .. tostring(v))
end
print("== utf8.char ==")
