print("== utf8.offset / codes ==")
do
  local s = "a" .. han .. "b" .. emoji .. "c"
  P("bytes", #s)
  P("off1", utf8.offset(s, 1))
  P("off2", utf8.offset(s, 2))
  P("off3", utf8.offset(s, 3))
  P("off4", utf8.offset(s, 4))
  P("off5", utf8.offset(s, 5))
  P("off6", utf8.offset(s, 6))
  P("off7", utf8.offset(s, 7))
  P("off-1", utf8.offset(s, -1))
  P("off-2", utf8.offset(s, -2))
  P("off-5", utf8.offset(s, -5))
  P("off-6", utf8.offset(s, -6))
  P("off 2 from 2", utf8.offset(s, 2, 2))
  P("off 1 from 5", utf8.offset(s, 1, 5))
  P("off 0", utf8.offset(s, 0))
  P("off 0 from 2", utf8.offset(s, 0, 2))
  P("off -1 from 2", utf8.offset(s, -1, 2))
  P(rec(utf8.offset, s, 1, 0))
  P(rec(utf8.offset, s, 1, #s + 1))
  P(rec(utf8.offset, s, 1, -#s - 1))
  P(rec(utf8.offset, s, 1.5))
  P(rec(utf8.offset, s))
  P(rec(utf8.offset, s, 1, "1"))
  -- Walking every code point of a string.
  local out = {}
  for p, c in utf8.codes(s) do out[#out + 1] = p .. ":" .. c end
  P("codes", table.concat(out, ","))
  out = {}
  for p, c in utf8.codes("") do out[#out + 1] = tostring(p) end
  P("codes empty", #out)
  P(rec(utf8.codes, "\xff"))
  P(rec(utf8.codes))
  P(rec(utf8.codes, 1))
  local it = utf8.codes(han)
  P("codes it", show(pcall(it, nil, 1)))
  P("codes it2", show(pcall(it, nil, 2)))
  P("codes it3", show(pcall(it, nil, 4)))
  P("codes it4", show(pcall(it, nil, 5)))
end
P("charpattern", utf8.charpattern)
P("escape", #("\xe4\xb8\xad"):gsub(utf8.charpattern, "#"), ("a" .. han):gsub(utf8.charpattern, "[]"))

