-- #s and s:len() agree, including for a number.
P("len eq", #"abc", ("abc"):len(), show(pcall(function() return #nil end)))
P("len num", show(pcall(function() return #12345 end)))
-- The __len metamethod is consulted for tables only.
do
  local t = setmetatable({}, {__len = function() return 42 end})
  P("__len", #t, t)
  P("__len str", #setmetatable({}, {__len = function() return "x" end}))
  P("__len err", show(pcall(function() return #setmetatable({}, {__len = function() return 1.5 end}) end)))
end
